    # 忽略。
    events = self._audit.events_by_type(
        wallet_id, audit.TYPE_NODE_REJOINED
    )
    seen: set[str] = set()
    for event in events:
        if list(event) != list(_AUDIT_OUTER_KEY_ORDER):
            raise RecoveryError(
